import subprocess
def run(a):
    import subprocess as sp
    r=sp.run(["./executable"]+a, capture_output=True, text=True, timeout=3)
    return r.returncode, r.stderr
def has_default(err, flag):
    # find line containing flag
    for line in err.splitlines():
        if flag in line:
            return "(default:" in line, line.strip()
    return (None, "")

for val in ["true","True","TRUE","1","t","T","false","False","FALSE","0","f","F","","x","maybe","yes","no","on","off","TRUE "," true"]:
    rc,err=run(["--version="+val,"--help"])
    # check version line
    found=False
    for line in err.splitlines():
        if "--version" in line:
            print(f"version={repr(val)} RC:{rc} line:{repr(line)}")
            found=True
            break
    if not found:
        print(f"version={repr(val)} RC:{rc} NO version line, err head:{repr(err[:200])}")
PY"}

