{"command": "python3 <<'PY'
import subprocess, os, shutil
def run(inp, cwd="/tmp/empty_test"):
    import subprocess as sp
    # ensure clean
    p="/tmp/empty_test/.git"
    if os.path.exists(p):
        shutil.rmtree(p)
    r=sp.run(["/workspace/executable"], capture_output=True, text=True, timeout=2, cwd=cwd, input=inp)
    exists=os.path.exists(p)
    head=""
    if exists:
        try:
            with open(os.path.join(p,"HEAD")) as f: head=f.read().strip()
        except: head="no HEAD"
    return r.returncode, r.stdout, r.stderr[:300], exists, head

for inp in ["y \n"," y\n","yy\n","y\n ","y\n\n","y\nmy branch\n","y\nmybranch\n"]:
    rc,out,err,ex,head=run(inp)
    print(f"input:{repr(inp)} RC:{rc} OUT:{repr(out)} EXISTS:{ex} HEAD:{repr(head)} ERR:{repr(err[:100])}")
PY"}

