{"command": "cat > main.go <<'GOEOF'
package main

import (
	"bufio"
	_ "embed"
	"encoding/json"
	"fmt"
	"log"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"sort"
	"strconv"
	"strings"
	"time"
)

//go:embed default_config.yml
var defaultConfig string

func main() {
	log.SetFlags(log.LstdFlags)
	prog := filepath.Base(os.Args[0])
	args := os.Args[1:]

	// parser state
	var (
		helpFlag         bool
		helpSet          bool // not needed, help without = is true
		versionVal       string // raw? Actually bool
		versionIsTrue    bool
		versionSeen      bool
		debugIsTrue      bool
		debugSeen        bool
		logsIsTrue       bool
		logsSeen         bool
		profileIsTrue    bool
		profileSeen      bool
		configIsTrue     bool
		configSeen       bool
		printDirIsTrue   bool
		printDirSeen     bool
		pathVal          string
		pathSeen         bool
		filterVal        string
		filterSeen       bool
		useConfigDirVal  string
		useConfigDirSeen bool
		workTreeVal      string
		workTreeSeen     bool
		gitDirVal        string
		gitDirSeen       bool
		useConfigFileVal string
		useConfigFileSeen bool
		screenModeVal    string
		screenModeSeen   bool
		positionals      []string
		unknownTokens    []string // for Unknown arguments supplied
		missingErr       string   // flag name for missing
		unexpectedArg    string
		panicType        string // "flag" or "positional" for panic message differences? Actually need to distinguish panic stacks
		shouldPanic      bool
		panicIsFlag      bool // true for "-" (addParsedFlag), false for "" (addParsedPositionalValue)
	)

	// helper maps
	isBoolFlag := func(name string) bool {
		switch name {
		case "h", "help", "v", "version", "d", "debug", "l", "logs", "profile", "c", "config", "cd", "print-config-dir":
			return true
		default:
			return false
		}
	}
	isStringFlag := func(name string) bool {
		switch name {
		case "p", "path", "f", "filter", "ucd", "use-config-dir", "w", "work-tree", "g", "git-dir", "ucf", "use-config-file", "sm", "screen-mode":
			return true
		default:
			return false
		}
	}
	// normalize flag name: flaggy treats all as same? Actually need to map short/long to canonical?
	// For our logic, we need to know which flag it is to set appropriate var.
	// We'll map name to canonical.
	canonical := func(name string) string {
		switch name {
		case "h", "help":
			return "help"
		case "p", "path":
			return "path"
		case "f", "filter":
			return "filter"
		case "v", "version":
			return "version"
		case "d", "debug":
			return "debug"
		case "l", "logs":
			return "logs"
		case "profile":
			return "profile"
		case "c", "config":
			return "config"
		case "cd", "print-config-dir":
			return "print-config-dir"
		case "ucd", "use-config-dir":
			return "use-config-dir"
		case "w", "work-tree":
			return "work-tree"
		case "g", "git-dir":
			return "git-dir"
		case "ucf", "use-config-file":
			return "use-config-file"
		case "sm", "screen-mode":
			return "screen-mode"
		default:
			return ""
		}
	}
	parseBoolVal := func(v string) bool {
		switch v {
		case "1", "t", "T", "TRUE", "true", "True":
			return true
		default:
			return false
		}
	}

	// iteration with separator handling
	seenSep := false
	i := 0
	for i < len(args) {
		arg := args[i]
		if seenSep {
			break
		}
		if arg == "--" {
			seenSep = true
			i++
			continue
		}
		if arg == "" {
			// check if this arg was consumed? No, we only reach here if not consumed.
			// panic for empty
			printPanic(false)
			return
		}
		if arg == "-" {
			printPanic(true)
			return
		}
		if strings.HasPrefix(arg, "-") {
			rest := strings.TrimLeft(arg, "-")
			if rest == "" {
				// all dashes like "---"
				printPanic(true)
				return
			}
			if strings.HasPrefix(rest, "=") {
				// flag empty, ignored (e.g., "-=foo", "--=foo")
				i++
				continue
			}
			if strings.Contains(rest, "=") {
				name, value, _ := strings.Cut(rest, "=")
				if name == "" {
					i++
					continue
				}
				c := canonical(name)
				if c == "help" {
					// help with = is unknown
					unknownTokens = append(unknownTokens, name+"="+value)
					i++
					continue
				}
				if c == "version" {
					versionSeen = true
					versionIsTrue = parseBoolVal(value)
					i++
