	// print help to stderr (with defaults based on true bools? For missing/unexpected, what defaults? Let's see: "--path --help" with missing? Actually missing overrides help, but what help defaults to show for missing case? Example "--path" alone (missing) => help without defaults? Or with? Let's check: "./executable --path" (missing) => help without defaults? Our earlier test for "--path" missing gave help without defaults (since no bool true). Good. For "--version --unknown" (unknown) => help without defaults? Actually that case gave help with no defaults? Wait "--version --unknown" where unknown missing => missing error, not unknown. Hmm.
	// For missing/unexpected, help should be printed with defaults for true bools that were parsed? Example "-v --path" where path missing and version true? Let's test: "-v --path" (version true + path missing) => missing error, but what help defaults? Should show version default? Let's test.
	printHelp(prog, version, debug, logs, profile, config, printDir)
	// then extra line
	if kind == "missing" {
		fmt.Fprintf(os.Stderr, "\nExpected a following arg for flag %s, but it did not exist.\n", detail)
