func printHelp(prog string, version, debug, logs, profile, config, printDir bool) {
	// base descriptions
	lines := []string{
		prog,
		"",
		"  Usage:",
		"    " + prog + " [git-arg]",
		"",
		"  Positional Variables: ",
		"    git-arg   Panel to focus upon opening lazygit. Accepted values (based on git terminology): status, branch, log, stash. Ignored if --filter arg is passed.",
		"  Flags: ",
	}
	// flag lines with descriptions (base)
	type flagInfo struct {
		short string
		long  string
		desc  string
		isBool bool
		isTrue bool
	}
	flags := []flagInfo{
		{"-h", "--help", "Displays help with available flag, subcommand, and positional value parameters.", false, false},
		{"-p", "--path", "Path of git repo. (equivalent to --work-tree=<path> --git-dir=<path>/.git/)", false, false},
		{"-f", "--filter", "Path to filter on in `git log -- <path>`. When in filter mode, the commits, reflog, and stash are filtered based on the given path, and some operations are restricted", false, false},
		{"-v", "--version", "Print the current version", true, version},
		{"-d", "--debug", "Run in debug mode with logging (see --logs flag below). Use the LOG_LEVEL env var to set the log level (debug/info/warn/error)", true, debug},
		{"-l", "--logs", "Tail lazygit logs (intended to be used when `lazygit --debug` is called in a separate terminal tab)", true, logs},
		{"", "--profile", "Start the profiler and serve it on http port 6060. See CONTRIBUTING.md for more info.", true, profile},
		{"-c", "--config", "Print the default config", true, config},
		{"-cd", "--print-config-dir", "Print the config directory", true, printDir},
		{"-ucd", "--use-config-dir", "override default config directory with provided directory", false, false},
		{"-w", "--work-tree", "equivalent of the --work-tree git argument", false, false},
		{"-g", "--git-dir", "equivalent of the --git-dir git argument", false, false},
		{"-ucf", "--use-config-file", "Comma separated list to custom config file(s)", false, false},
		{"-sm", "--screen-mode", "The initial screen-mode, which determines the size of the focused panel. Valid options: 'normal' (default), 'half', 'full'", false, false},
	}
	for _, f := range flags {
		desc := f.desc
		if f.isBool && f.isTrue {
			desc += " (default: false)"
		}
		var line string
		if f.short == "" {
			// profile: 7 spaces + long?
			// observed: "       --profile            Start..."
			// That's 7 spaces before --profile? Let's construct exactly as observed.
			// For others: "    -h --help               Displays..."
			// We need to replicate spacing exactly. Easiest: hardcode spacing per flag as observed.
			// We'll use map of exact prefix.
			line = formatFlagLine(f.short, f.long, desc)
		} else {
			line = formatFlagLine(f.short, f.long, desc)
		}
		lines = append(lines, line)
	}
	lines = append(lines, "")
	text := strings.Join(lines, "\n")
	// help goes to stderr
	fmt.Fprintln(os.Stderr, text)
}

func formatFlagLine(short, long, desc string) string {
	// Replicate exact spacing from observed help.
	// We have observed lines:
	// "    -h --help               Displays..."
	// "    -p --path               Path..."
	// "    -f --filter             Path..."
	// "    -v --version            Print..."
	// "    -d --debug              Run..."
	// "    -l --logs               Tail..."
	// "       --profile            Start..."
	// "    -c --config             Print..."
	// "    -cd --print-config-dir   Print..."
	// "    -ucd --use-config-dir     override..."
	// "    -w --work-tree          equivalent..."
	// "    -g --git-dir            equivalent..."
	// "    -ucf --use-config-file    Comma..."
	// "    -sm --screen-mode        The..."
	// The spacing between long and desc appears to align desc at same column? Let's compute column.
	// For "-h --help" (9 chars inc dash?) Actually "    " (4) + "-h" (2) + " " (1) + "--help" (6) = 13, then spaces to desc.
	// For "       --profile" (7 + 9 =16?) Hmm.
	// Instead of computing, hardcode prefix per flag as observed.
	var prefix string
	switch long {
	case "--help":
		prefix = "    -h --help               "
	case "--path":
		prefix = "    -p --path               "
	case "--filter":
		prefix = "    -f --filter             "
	case "--version":
		prefix = "    -v --version            "
	case "--debug":
		prefix = "    -d --debug              "
	case "--logs":
		prefix = "    -l --logs               "
	case "--profile":
		prefix = "       --profile            "
	case "--config":
		prefix = "    -c --config             "
	case "--print-config-dir":
		prefix = "    -cd --print-config-dir   "
	case "--use-config-dir":
		prefix = "    -ucd --use-config-dir     "
	case "--work-tree":
		prefix = "    -w --work-tree          "
	case "--git-dir":
		prefix = "    -g --git-dir            "
	case "--use-config-file":
		prefix = "    -ucf --use-config-file    "
	case "--screen-mode":
		prefix = "    -sm --screen-mode        "
	default:
		prefix = "    " + short + " " + long + " "
	}
	return prefix + desc
}

