func getGitVersion() string {
	cmd := exec.Command("git", "--version")
	out, _ := cmd.Output()
	s := string(out)
	// TrimPrefix before TrimSpace
	if strings.HasPrefix(s, "git version ") {
		s = strings.TrimPrefix(s, "git version ")
	}
	s = strings.TrimSpace(s)
	return s
}

func getConfigDir(useConfigDir string) string {
	if useConfigDir != "" {
		return filepath.Clean(useConfigDir)
	}
	if cfg := os.Getenv("CONFIG_DIR"); cfg != "" {
		return filepath.Clean(cfg)
	}
	if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" {
		expanded := expandXDG(xdg)
		if filepath.IsAbs(expanded) {
			return filepath.Join(expanded, "lazygit")
		}
		// else fallback to HOME
	}
	home := os.Getenv("HOME")
	// Use home + "/.config/lazygit" then clean (to match "/.config/lazygit" for empty home)
	return filepath.Clean(home + "/.config/lazygit")
}

func expandXDG(xdg string) string {
	home := os.Getenv("HOME")
	if strings.HasPrefix(xdg, "~/") {
		return filepath.Join(home, strings.TrimPrefix(xdg, "~/"))
	}
	if xdg == "~" {
		return home
	}
	if strings.HasPrefix(xdg, "~") {
		// "~foo" => home + "/foo"? Observed: "~foo" with HOME=/tmp/home => /tmp/home/foo
		// So strip leading "~" and join?
		rest := strings.TrimPrefix(xdg, "~")
		// rest may be "foo" or "foo/bar", join with home
		// If rest starts with "/",? "~/" already handled, so rest is like "foo"
		return filepath.Join(home, rest)
	}
	if xdg == "$HOME" {
		return home
	}
	if strings.HasPrefix(xdg, "$HOME/") {
		return filepath.Join(home, strings.TrimPrefix(xdg, "$HOME/"))
	}
	if strings.HasPrefix(xdg, "$HOME") {
		// "$HOMEfoo" => home + "foo"? Observed: "$HOMEfoo" => /tmp/home/foo
		rest := strings.TrimPrefix(xdg, "$HOME")
		return filepath.Join(home, rest)
	}
	return xdg
}

func getStateDir() (string, error) {
	// For logs default path (when no override): need to create dir? Actually getStateDir returns base?
	// Logic: if XDG_STATE_HOME non-empty and absolute (after expand?) => use it, else HOME/.local/state
	// Expand same as XDG?
	if xdg := os.Getenv("XDG_STATE_HOME"); xdg != "" {
		expanded := expandXDG(xdg)
		if filepath.IsAbs(expanded) {
