		return line
	}
	// Extract time, level, msg
	timeStr, _ := m["time"].(string)
	levelStr, _ := m["level"].(string)
	msgStr, _ := m["msg"].(string)
	// time format: "2006-01-02T15:04:05Z" -> "Jan _2 15:04:05"
	t, err := time.Parse(time.RFC3339, timeStr)
