func getLogPath(useConfigDir string) (string, bool, error) {
	// returns logPath, isOverride, error (for creation failure)
	// If useConfigDir non-empty or CONFIG_DIR non-empty => override path: <configDir>/development.log, no creation, no error for missing dir?
	// Else state path: <state>/lazygit/development.log, with creation attempt?
	var configDir string
	var isOverride bool
	if useConfigDir != "" {
		configDir = filepath.Clean(useConfigDir)
		isOverride = true
	} else if cfg := os.Getenv("CONFIG_DIR"); cfg != "" {
		configDir = filepath.Clean(cfg)
		isOverride = true
	}
	if isOverride {
		return filepath.Join(configDir, "development.log"), true, nil
	}
	// state path
	if xdg := os.Getenv("XDG_STATE_HOME"); xdg != "" {
		expanded := expandXDG(xdg)
		if filepath.IsAbs(expanded) {
			// need to ensure <expanded>/lazygit exists? Try mkdir
			dir := filepath.Join(expanded, "lazygit")
			if err := os.MkdirAll(dir, 0755); err != nil {
				return "", false, fmt.Errorf("could not create any of the following paths: %s", dir)
			}
			// Also check if dir creation succeeded but is it writable? MkdirAll may succeed even if parent is /nonexistent? Actually for /nonexistent2/lazygit, MkdirAll tries to create /nonexistent2, fails due to permission? Let's see: / is writable by root only, agent can't create /nonexistent2, so fails. Good.
			return filepath.Join(dir, "development.log"), false, nil
		}
	}
	home := os.Getenv("HOME")
	// For HOME empty, original error is "could not create any of the following paths: /.local/state/lazygit" (no Tailing prefix, RC1)
	// For HOME=/nonexistent (non-creatable), same with that path.
	// Try to determine dir:
	var dir string
	if home == "" {
		dir = "/.local/state/lazygit"
	} else {
		dir = filepath.Join(home, ".local", "state", "lazygit")
	}
	if err := os.MkdirAll(dir, 0755); err != nil {
		return "", false, fmt.Errorf("could not create any of the following paths: %s", dir)
	}
	return filepath.Join(dir, "development.log"), false, nil
}

func doLogs(useConfigDir string) {
	logPath, _, err := getLogPath(useConfigDir)
	if err != nil {
		log.Fatal(err)
	}
	// Print Tailing line to stdout
	fmt.Printf("Tailing log file %s\n\n", logPath)
	// Check file exists
	if _, err := os.Stat(logPath); err != nil {
		log.Fatalf("Log file does not exist. Run `lazygit --debug` first to create the log file")
	}
	// Tail file: print existing content formatted, then follow
	// For simplicity, read entire file, format each line, print, then poll for new lines
	file, err := os.Open(logPath)
	if err != nil {
		log.Fatalf("Log file does not exist. Run `lazygit --debug` first to create the log file")
	}
	defer file.Close()
	// Read all lines and format
	reader := bufio.NewReader(file)
	var offset int64
	// Get initial size? We'll just read line by line
	for {
		line, err := reader.ReadString('\n')
		if err != nil {
			break
		}
		// line includes \n, strip trailing \n for parsing? Keep as is for non-json?
		trimmed := strings.TrimRight(line, "\r\n")
		fmt.Println(formatLogLine(trimmed))
		offset, _ = file.Seek(0, 1)
		_ = offset
	}
	// Follow: poll every 200ms for new content
	for {
		time.Sleep(200 * time.Millisecond)
		// Check for new lines
		for {
			line, err := reader.ReadString('\n')
			if err != nil {
				break
			}
			trimmed := strings.TrimRight(line, "\r\n")
			fmt.Println(formatLogLine(trimmed))
		}
		// Also handle last line without newline? Our initial read only handles lines with \n. For file that ends without \n? Unlikely (log lines end with \n). For "dummy" file with "dummy\n", it ends with \n, good.
		// If file was truncated? Ignore.
	}
}

